# Define the piecewise gain function
def piecewise_gain(mass, threshold=1e-3, alpha=1.5, beta=2, k=1e-3):
    if mass < threshold:
        # Slow gain for small masses (logarithmic or gradual power law)
        return (mass**alpha) / (mass**alpha + k)
    else:
        # Fast gain for larger masses (steeper power law or exponential)
        return (mass**beta) / (mass**beta + k)

# Apply the piecewise gain function to the energy calculations
adjusted_energy_piecewise_gain = [
    ((mc2 - quantum) / piecewise_gain(mass)) + pattern_factor
    for mc2, quantum, mass in zip(expanded_expected_energies, expanded_calculated_energies, expanded_masses)
]

# Calculate the relative differences between the adjusted energies and the expected E=mc^2 values
piecewise_gain_relative_differences = [
    abs(expected - adjusted) / expected if expected != 0 else None
    for expected, adjusted in zip(expanded_expected_energies, adjusted_energy_piecewise_gain)
]

# Add the adjusted energies and relative differences to the dataframe for further analysis
df_expanded_comparison['Piecewise Gain Middleware Energy (J)'] = adjusted_energy_piecewise_gain
